import assert from 'node:assert/strict';import{createRequire}from'node:module';import{mkdir,writeFile}from'node:fs/promises';const r=createRequire(process.env.SDS_BROWSER_MODULES+'/package.json');const b=await r('puppeteer-core').launch({executablePath:'/usr/local/bin/google-chrome',headless:true,args:['--no-sandbox']});const origin=process.env.SDS_PREVIEW_ORIGIN||'http://127.0.0.1:31861',out=process.env.SDS_CONTROLS_OUT||'/tmp/sds-controls';await mkdir(out,{recursive:true});const report=[];
try{for(const width of JSON.parse(process.env.SDS_CONTROL_WIDTHS||'[390,768,1440]'))for(const theme of JSON.parse(process.env.SDS_CONTROL_THEMES||'["drafting","dark"]')){const c=await b.createBrowserContext();await c.overridePermissions(origin,['clipboard-read','clipboard-write','clipboard-sanitized-write']);const p=await c.newPage();p.setDefaultNavigationTimeout(60000);await p.setViewport({width,height:900});await p.evaluateOnNewDocument(t=>localStorage.setItem('sdd-theme',t),theme);console.log('CONTROL_NAV',width,theme);await p.goto(origin,{waitUntil:'domcontentloaded'});await p.waitForSelector('[data-proof] button');await p.waitForFunction(()=>performance.getEntriesByName('sdd:react-ready').length>0);const toggle='button[title*="theme"]';await p.focus(toggle);await p.keyboard.press('Enter');await p.waitForFunction(t=>document.documentElement.dataset.theme===t,{},theme==='dark'?'drafting':'dark');await p.waitForFunction(()=>!document.documentElement.matches(':active-view-transition'));await p.keyboard.press('Space');await p.waitForFunction(t=>document.documentElement.dataset.theme===t,{},theme);await p.waitForFunction(()=>!document.documentElement.matches(':active-view-transition'));if(width===390){await p.focus('[data-menu-toggle]');await p.keyboard.press('Enter');assert.equal(await p.$eval('#sdd-menu',e=>e.matches(':popover-open')),true);await p.keyboard.press('Escape');assert.equal(await p.$eval('#sdd-menu',e=>e.matches(':popover-open')),false);}await p.locator('[data-proof] button').click();await p.waitForFunction(()=>[...document.querySelectorAll('button[aria-pressed]')].some(e=>e.textContent.includes('What an AI sees')&&e.getAttribute('aria-pressed')==='true'));await p.$$eval('[data-agent-trigger]',els=>els.find(e=>e.getClientRects().length)?.focus());await p.keyboard.press('Enter');assert.equal(await p.$$eval('[popover]',els=>els.some(e=>e.matches(':popover-open'))),true);await p.screenshot({path:out+'/agent-'+width+'-'+theme+'.jpg',fullPage:true});await p.keyboard.press('Escape');await p.goto(origin+'/x402#setup',{waitUntil:'domcontentloaded'});await p.waitForSelector('[role=tab]');await p.focus('[role=tab][aria-selected=true]');for(const key of['ArrowRight','ArrowRight','ArrowLeft']){const old=await p.$eval('[role=tab][aria-selected=true]',e=>e.textContent);await p.keyboard.press(key);await p.waitForFunction(v=>document.querySelector('[role=tab][aria-selected=true]').textContent!==v,{},old);assert.equal(await p.$eval('[role=tab][aria-selected=true]',e=>document.activeElement===e),true);}await p.bringToFront();await p.locator('#setup button:not([role=tab])').click();await p.waitForFunction(()=>document.querySelector('#setup button:not([role=tab])').textContent==='Copied');assert.equal(await p.evaluate(()=>navigator.clipboard.readText()),await p.$eval('#setup-panel',e=>e.textContent));await p.screenshot({path:out+'/setup-'+width+'-'+theme+'.jpg',fullPage:true});report.push({width,theme,themeKeyboard:true,menuEscape:width===390,agentKeyboard:true,setupArrowKeys:true,clipboard:true});await c.close();console.log('CONTROLS',width,theme)}}finally{await b.close();await writeFile(out+'/report.json',JSON.stringify(report,null,2));}
